            "deny_by_default": true,
            "preauth_grants_operational_access": "DENY",
            "server_side_enforcement": true
          }
        }
      ]
    },
    {
      "acceptance_checks": [
        "La respuesta expone únicamente el outcome funcional, un correlation_id generado por servidor y, cuando corresponda, el código de error canónico. No se exponen errores crudos, credenciales, tokens internos ni razones sensibles."
      ],
      "evidence_refs": [
        "supabase://lf_ops.reglas/306"
      ],
      "outcome": "La respuesta expone únicamente el outcome funcional, un correlation_id generado por servidor y, cuando corresponda, el código de error canónico. No se exponen errores crudos, credenciales, tokens internos ni razones sensibles.",
