            "internal_token_exposure": "DENY",
            "required_fields": [
              "outcome",
              "correlation_id"
            ]
          }
        }
      ]
    },
    {
      "acceptance_checks": [
        "El Login se comunica exclusivamente con una capa de autenticación del lado servidor. El navegador no verifica credenciales por sí mismo. Si la identidad no puede verificarse válidamente, no se crea sesión ni se concede acceso."
      ],
      "evidence_refs": [
        "supabase://lf_ops.reglas/303"
      ],
      "outcome": "El Login se comunica exclusivamente con una capa de autenticación del lado servidor. El navegador no verifica credenciales por sí mismo. Si la identidad no puede verificarse válidamente, no se crea sesión ni se concede acceso.",
      "requirement_id": "REQ-SBX-B2B-R-AUTH-FAIL-CLOSED",
