            "lockout_source": "PERSISTED_ATTEMPTS",
            "origin": "SANDBOX_INTEGRATION",
            "password_in_record": "DENY",
            "record": [
              "account_ref_or_normalized_email",
              "occurred_at",
              "outcome",
              "correlation_id"
