            "reset_on": "AUTHENTICATED",
            "rollback_dir": "apps/time-service/src/main/resources/db/rollback (fuera de la ubicación de Flyway)",
            "sandbox_policy": "EXISTING_LOGIN_POLICY",
            "schema": {
              "columns": {
                "account_id": "bigint NULL, FK a sbx_b2b_accounts(id); NULL si el correo no existe",
