                "email_normalized": "varchar(254) NOT NULL",
                "id": "bigint identidad, PK",
                "outcome": "varchar(24) NOT NULL, CHECK INVALID_CREDENTIALS | RATE_LIMITED",
                "updated_at": "timestamptz NOT NULL DEFAULT now() (STD-DB-04); la tabla es de solo inserción"
