                "password_hash",
                "password_plain"
              ],
              "index": [
                "(email_normalized, created_at)"
              ],
              "table": "sbx_b2b_login_attempts"
            },
            "standards": [
              "STD-DB-01..09 aplican: tablas en plural snake_case, PK bigint identidad, nombres de constraints e índices por defecto de Postgres, created_at/updated_at, RLS activo sin privilegios a PUBLIC (STD-DB-06), migración V<n>__<descripcion>.sql con su rollback U<n>__<descripcion>.sql en el directorio de rollback: aplicar, revertir y reaplicar conservando los datos existentes (STD-DB-08)"
            ],
            "store": "SANDBOX_RELATIONAL_DB",
            "survives_restart": true
          }
        }
      ]
    },
    {
      "acceptance_checks": [
        "La sesión emitida tras un resultado AUTHENTICATED se registra en el almacén persistente (solo el hash del token, la cuenta, creación, último uso, vencimiento y revocación). La inactividad y la concurrencia de sesiones se aplican desde ese registro. Cerrar sesión revoca el registro; un token revocado o vencido deja de ser válido aunque el servicio se reinicie."
      ],
      "evidence_refs": [
        "supabase://lf_ops.reglas/336"
      ],
      "outcome": "La sesión emitida tras un resultado AUTHENTICATED se registra en el almacén persistente (solo el hash del token, la cuenta, creación, último uso, vencimiento y revocación). La inactividad y la concurrencia de sesiones se aplican desde ese registro. Cerrar sesión revoca el registro; un token revocado o vencido deja de ser válido aunque el servicio se reinicie.",
      "requirement_id": "REQ-SBX-B2B-R-DATA-SESSIONS",
      "rule_code": "SBX-B2B-R-DATA-SESSIONS",
      "rules": [
